// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;

    function setUp() public {
        c = new airPort();
    }

    function testFuzz_property(address from, address token, address[] memory tos, uint256 v) public {
        vm.assume(tos.length < 100);

        RecordingToken rec = new RecordingToken();

        (bool ok,) = token.call(abi.encodeWithSignature("transferFrom(address,address,uint256)", from, tos.length > 0 ? tos[0] : address(0), v));

        bool callOk;

        try c.transfer(from, address(rec), tos, v) returns (bool r) {
            callOk = r;
        } catch {
            callOk = false;
        }

        assertTrue(!callOk || (tos.length > 0 && rec.calls() == tos.length && rec.totalAmount() == v * uint256(tos.length)));
    }
}

contract RecordingToken {
    uint256 public calls;
    uint256 public totalAmount;
    mapping(address => uint256) public perRecipient;

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        calls++;
        totalAmount += amount;
        perRecipient[to]++;
        return true;
    }
}
